#include <iostream>
#include <vector>
#include <algorithm>
#include <cstdlib>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, B;
    cin >> n >> B;
    vector<int> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }

    int ce = 0, co = 0;
    vector<int> count;
    for (int i = 0; i < n - 1; i++) {
        if (a[i] % 2 == 0) {
            ce++;
        } else {
            co++;
        }
        if (co == ce) {
            int diff = std::abs(a[i] - a[i + 1]);
            count.push_back(diff);
        }
    }

    std::sort(count.begin(), count.end());

    int sum = 0;
    int cou = 0;
    for (size_t i = 0; i < count.size(); i++) {
        sum += count[i];
        if (sum > B) {
            break;
        }
        cou++;
    }

    cout << cou << "\n";

    return 0;
}

